T pop() {
  while (true) {
    Node* t = top.load();
    if (t == nullptr) return EMPTY;
    hp[me] = t;                 // 1. publish
    full_fence();               // store before reload
    if (top.load() != t)        // 2. validate
      continue;                 //    t may be gone: retry
    Node* n = t->next;          // safe: t is protected
    if (top.cas(t, n)) {
      T data = t->data;
      hp[me] = nullptr;         // stop protecting
      retire(t);                // not free(t)
      return data;
    }
  }
}

use crossbeam_epoch::{self as epoch, Atomic};
use std::sync::atomic::Ordering::{Acquire, Relaxed, Release};

struct Node<T> { data: T, next: Atomic<Node<T>> }
pub struct Stack<T> { head: Atomic<Node<T>> }

impl<T: Copy> Stack<T> {
    pub fn pop(&self) -> Option<T> {
        let guard = epoch::pin(); // enter a critical section
        loop {
            let head = self.head.load(Acquire, &guard);
            let h = unsafe { head.as_ref() }?; // valid while pinned
            let next = h.next.load(Relaxed, &guard);
            if self.head
                .compare_exchange(head, next, Release, Relaxed, &guard)
                .is_ok()
            {
                // retire: destroyed once the epoch has moved on
                unsafe { guard.defer_destroy(head) };
                return Some(h.data);
            }
        }
    } // guard dropped here: the thread unpins
}

struct foo { int a; char b; long c; };
DEFINE_SPINLOCK(foo_mutex);
struct foo __rcu *gbl_foo;

int foo_get_a(void)                      /* reader */
{
        int retval;
        rcu_read_lock();
        retval = rcu_dereference(gbl_foo)->a;
        rcu_read_unlock();
        return retval;
}

void foo_update_a(int new_a)             /* updater */
{
        struct foo *new_fp = kmalloc_obj(*new_fp);
        struct foo *old_fp;

        spin_lock(&foo_mutex);           /* updaters still exclude each other */
        old_fp = rcu_dereference_protected(gbl_foo,
                        lockdep_is_held(&foo_mutex));
        *new_fp = *old_fp;               /* copy */
        new_fp->a = new_a;               /* update the copy */
        rcu_assign_pointer(gbl_foo, new_fp); /* publish */
        spin_unlock(&foo_mutex);
        synchronize_rcu();               /* wait for a grace period */
        kfree(old_fp);                   /* reclaim */
}
